  // ── Department nav initialization ────────────────────────────────

  function buildTalentContent() {
    const el = document.getElementById('talentContent');
    if (!el) return;
    // Guard: if profiles tab is active, don't overwrite it with concerns content
    if (_talentTab === 'profiles') return;
    try {
      const dept = _currentDept || 'hr';
      if (_talentTab === 'all') {
        // Route "All Insights" to dept-specific lens
        if (dept === 'hr')         el.innerHTML = renderHRAnalytics(_filteredConcerns);
        else if (dept === 'programming') el.innerHTML = renderProgrammingAnalytics(_filteredConcerns);
        else if (dept === 'leadership')  el.innerHTML = renderLeadershipAnalytics(_filteredConcerns);
        else if (dept === 'data')        el.innerHTML = renderDataAnalytics(_filteredConcerns);
        else if (dept === 'kb')          el.innerHTML = renderLeadershipAnalytics(_filteredConcerns);
        else el.innerHTML = renderLeadershipAnalytics(_filteredConcerns); // fallback
      } else if (_talentTab === 'program') el.innerHTML = renderProgrammingAnalytics(_filteredConcerns);
      else if (_talentTab === 'hr')      el.innerHTML = renderHRAnalytics(_filteredConcerns);
      else if (_talentTab === 'reviews') {
        if (dept === 'programming') el.innerHTML = renderProgrammingReviews();
        else if (dept === 'training') el.innerHTML = renderTrainingReviews();
        else el.innerHTML = renderTalentReviews();
      }
      else if (_talentTab === 'log')     el.innerHTML = renderTalentLog();
      else if (_talentTab === 'hiring')  el.innerHTML = (typeof window._hrHiringFileCabinet === 'function') ? window._hrHiringFileCabinet() : '<div style="padding:2rem;color:var(--muted)">Hiring records not available.</div>';
      else if (_talentTab === 'dol') {
        if (typeof window.renderDOLReport === 'function') { window.renderDOLReport(el); }
        else el.innerHTML = '<div style="padding:2rem;color:var(--muted)">DOL Report not available.</div>';
      }
      else if (_talentTab === 'definitions') el.innerHTML = (typeof window._hrViewDefinitions === 'function') ? window._hrViewDefinitions() : '<div style="padding:2rem;color:var(--muted)">Definitions not available.</div>';
    } catch(e) {
      document.getElementById('talentContent').innerHTML = `<div style="padding:2rem;color:var(--muted);text-align:center">Render error: ${e.message}</div>`;
      console.error('Talent dashboard error:', e);
    }
  }

  // Update tab labels and layout based on dept
  function initTalentTabsForDept(dept) {
    // Full tab list: profiles, all (concerns), program, hr, reviews, log, hiring, definitions
    const TAB_IDS = ['profiles','all','program','hr','reviews','log','hiring','dol','definitions'];
    // Dept → which tabs are visible (strict isolation — only leadership/data see cross-dept tabs)
    const TAB_MAP = {
      kb:          ['profiles','definitions'],
      leadership:  ['all','definitions'],
      data:        ['profiles','all','program','hr','reviews','log','hiring','dol','definitions'],
      hr:          ['profiles','all','reviews','log','hiring','dol','definitions'],
      programming: ['profiles','all','reviews','definitions'],
      finance:     ['profiles','all','definitions'],
      training:    ['profiles','all','reviews','definitions'],
    };
    const allowed = new Set(TAB_MAP[dept] || ['all']);

    // Label override for the "all" tab per dept
    const labels = {
      hr:          '👔 HR Overview',
      programming: '🎯 Site Overview',
      leadership:  '⭐ Leadership View',
      data:        '📈 Full Analytics',
      kb:          '🌟 Exec Summary',
      finance:     '💰 Finance View',
      training:    '📚 Training View',
    };
    const allTab = document.getElementById('talentTab-all');
    if (allTab) allTab.textContent = labels[dept] || '📊 Overview';

    // Show/hide each tab strictly
    for (const id of TAB_IDS) {
      const el = document.getElementById('talentTab-' + id);
      if (!el) continue;
      el.style.display = allowed.has(id) ? '' : 'none';
    }

    // Also intercept onclick on ALL tab buttons to block cross-dept toggling
    // Only leadership and data can click tabs outside their dept-allowed set
    document.querySelectorAll('[id^="talentTab-"]').forEach(btn => {
      const tabId = btn.id.replace('talentTab-','');
      if (!allowed.has(tabId)) {
        btn.onclick = null; // already hidden, double-lock
      }
    });
  }

  // ── Finance analytics panel ────────────────────────────────────

  // ── Override showPanel to trigger dept analytics panels ─────────
  (function() {
    const _base = window.showPanel;
    // Idle-safe wrapper: schedule non-critical work when browser is free
    const _idle = (fn, timeout) => {
      if (typeof requestIdleCallback === 'function') requestIdleCallback(fn, { timeout: timeout || 1500 });
      else setTimeout(fn, 0);
    };
    window.showPanel = function(id, btn) {
      // Panel switch itself is synchronous — must be instant for perceived responsiveness
      if (_base) _base(id, btn);
      else {
        document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('.sidebar-link').forEach(l => l.classList.remove('active'));
        if (id === 'policies' && typeof fetchOpsManual === 'function') fetchOpsManual(false);
        const panelEl = document.getElementById('panel-' + id);
        if (panelEl) panelEl.classList.add('active');
        const linkEl = btn || document.querySelector('[data-panel="' + id + '"]');
        if (linkEl) linkEl.classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
      // Heavy analytics panels — deferred to idle so panel transition feels instant
      if (id === 'advocacy') {
        _idle(() => { if (typeof advOnPanelOpen === 'function') advOnPanelOpen(); });
      }
      if (id === 'talent') {
        _idle(() => {
          buildTalentDashboard(false);
          if (!window._talentLoaded) setTimeout(() => initTalentFilters(), 400);
          const _sp2Dept = (window.NJTC_SESSION||{}).dept||'hr';
          if (['hr','data','kb','finance','programming','training'].includes(_sp2Dept)) {
            setTimeout(() => { if (typeof setTalentTab === 'function') setTalentTab('profiles'); }, 200);
          } else if (_sp2Dept === 'leadership') {
            setTimeout(() => { if (typeof setTalentTab === 'function') setTalentTab('all'); }, 200);
          }
        });
      }
      if (id === 'finance-analytics')  _idle(() => buildFinanceAnalytics());
      if (id === 'training-analytics') _idle(() => buildTrainingAnalytics());
      if (id === 'kpi-analytics')      _idle(() => buildKPIAnalytics());
      if (id === 'tap-standalone') {
        _idle(function() {
          var overviewEl = document.getElementById('tap-content-overview');
          if (overviewEl && !overviewEl.dataset.loaded) {
            overviewEl.dataset.loaded = '1';
            if (window.NJTCTapDash && typeof window.NJTCTapDash.renderTab === 'function') {
              window.NJTCTapDash.renderTab('overview', overviewEl);
            }
          }
        });
      }
      if (id === 'sy-analytics')  { if (window.sya) _idle(() => window.sya.onPanelOpen()); }
      if (id === 'pearl-ops')     { if (window.po)  _idle(() => window.po.onPanelOpen(), 800); }
      if (id === 'iready-lab')    { if (window.irlab) _idle(() => window.irlab.onPanelOpen(), 800); }
      if (id === 'knowtion')      { _idle(() => { if (window.kn) window.kn.build((window.NJTC_SESSION||{}).dept || 'all'); }); }
      // Program Pulse button visibility — show on pearl-ops and home for allowed depts
      _idle(() => { try { if (window.pds) window.pds.updateVisibility((window.NJTC_VIEW_DEPT||(window.NJTC_SESSION||{}).dept||'')); } catch(_e){} });
    };
  })();

  // ════════════════════════════════════════════════════════════════


  // ── Global data bootstrap ──────────────────────────────────────────────────
  // NOTE: Bootstrap is handled by the staggered init() function above.
  // All data sources are loaded with progressive timing to avoid bandwidth contention.
  // Pearl: T+800ms | HR+Concerns: T+1200ms | iReady+SY: T+1800ms
  // This IIFE intentionally left empty to avoid double-fetching.
  (function bootstrapData() {
    // All data prefetching now managed by init() with staggered timing.
    // Do not fire fetches here — they would contend with init() fetches
    // and cause the main thread freeze we are eliminating.
  })();

  // ── Exec Dashboard: robust multi-signal render engine ─────────────────────
  // Works on any network speed. Fires on: poll, Pearl re-render, iReady load,
  // panel activation. Tracks data fingerprint — only re-paints when data changes.
  (function() {
    var _lastFP = '';
    var _pollCount = 0;
    var _pollDone = false;
    var _stableHits = 0;
    var _INTERVALS = [400,600,800,1000,1200,1500,2000,2500,3000];

    function _isDept(dept) { return ['leadership','data','kb'].includes(dept||''); }

    function _fingerprint() {
      try {
        var st  = (window.po    && typeof window.po.getStats==='function')    ? window.po.getStats()    : null;
        var irl = (window.irlab && typeof window.irlab.getSummary==='function') ? window.irlab.getSummary() : null;
        return [
          st  ? (st.scholAttPct||'')  : '',
          st  ? (st.schoolCount||'')  : '',
          st  ? (st.sessions||'')     : '',
          st  ? (st.activeTutors||'') : '',
          irl ? (irl.mathRows||'')    : '',
          irl ? (irl.elaRows||'')     : '',
          irl ? (irl.mathMedianPctAllYears||'') : '',
          irl ? (irl.elaMedianPctAllYears||'')  : ''
        ].join('|');
      } catch(e) { return ''; }
    }

    function _hasData() {
      try {
        if (window.po && typeof window.po.getStats==='function') {
          var s=window.po.getStats();
          if (s && (s.scholAttPct!==null || s.schoolCount>0 || s.sessions>0)) return true;
        }
        if (window.irlab && typeof window.irlab.getSummary==='function') {
          var i=window.irlab.getSummary();
          if (i && (i.mathRows>0 || i.elaRows>0)) return true;
        }
      } catch(e) {}
      return false;
    }

    function _render(force) {
      var dept = (window.NJTC_SESSION||{}).dept||'';
      if (!_isDept(dept)) return;
      var hp = document.getElementById('panel-home');
      if (!hp || !hp.classList.contains('active')) return;
      var fp = _fingerprint();
      if (!force && fp && fp===_lastFP) return;
      _lastFP = fp;
      // Use requestIdleCallback if available — only paint when browser is idle
      // Falls back to setTimeout(0) which still yields a task boundary
      var _doRender = function() {
        try { if (typeof window.buildExecDashboard === 'function') window.buildExecDashboard(dept); } catch(e) { console.warn('[ExecDash] render err:',e.message); }
      };
      if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(_doRender, { timeout: 2000 });
      } else {
        setTimeout(_doRender, 0);
      }
    }

    // Polling loop — escalating delays, min 5 polls, stops after 2 stable data-confirmed rounds
    function _poll() {
      if (_pollDone) return;
      _render(false);
      var hasData = _hasData();
      if (hasData) _stableHits++; else _stableHits = 0;
      if (_stableHits >= 2 && _pollCount >= 5) { _pollDone = true; return; }
      var delay = _INTERVALS[Math.min(_pollCount, _INTERVALS.length-1)];
      _pollCount++;
      if (_pollCount <= 75) setTimeout(_poll, delay); // ~2 min max on slow network
    }
    setTimeout(_poll, 400);

    // Re-render on panel-home activation
    var _origSP_exec = window.showPanel;
    window.showPanel = function(id, btn) {
      if (typeof _origSP_exec==='function') _origSP_exec(id, btn);
      if (id==='home') setTimeout(function(){ _render(true); }, 80);
    };

    // Expose for external trigger (Pearl MutationObserver already wired above)
    window._execDashRefresh = function(force) { _render(force===true); };

    // MutationObserver on Pearl panel — debounced so it doesn't fire on every cell update
    (function _watchPearl() {
      var panel = document.getElementById('poMainContent') || document.getElementById('panel-pearl-ops');
      if (!panel) { setTimeout(_watchPearl, 500); return; }
      var _pearDebounce = null;
      new MutationObserver(function() {
        var hp = document.getElementById('panel-home');
        if (hp && hp.classList.contains('active')) {
          var dept=(window.NJTC_SESSION||{}).dept||'';
          if (_isDept(dept)) {
            clearTimeout(_pearDebounce);
            _pearDebounce = setTimeout(function(){ _render(false); }, 600); // 600ms debounce
          }
        }
      }).observe(panel, { childList:true, subtree:false }); // subtree:false — only direct children
    })();

    // Patch irlab: watch for data arrival — run at idle
    (function _watchIrlab() {
      if (!window.irlab) { setTimeout(_watchIrlab, 600); return; }
      if (window.irlab._execWatched) return;
      window.irlab._execWatched = true;
      var _ic = 0;
      (function _chk() {
        try {
          var irl = window.irlab.getSummary();
          if (irl && (irl.mathRows>0 || irl.elaRows>0)) {
            // Use idle callback — don't interrupt the user
            if (typeof requestIdleCallback === 'function') requestIdleCallback(function(){ _render(false); }, { timeout: 3000 });
            else setTimeout(function(){ _render(false); }, 200);
            return;
          }
        } catch(e) {}
        if (_ic++ < 40) setTimeout(_chk, 2000); // slower polling — 40 checks over ~80s max
      })();
    })();

  })();

  // ── showPanel KPI hook: show/hide QR section ───────────────
  (function() {
    var _origSP2 = window.showPanel;
    window.showPanel = function(id, btn) {
      _origSP2(id, btn);
      var qrs = document.getElementById('kpiQRSection');
      if (!qrs) return;
      if (id === 'kpi-analytics') {
        var dept = (window.NJTC_SESSION||{}).dept||'';
        qrs.style.display = 'block';
        // Data dept gets the full upload/override zone; all others see report-only
        var dz = document.getElementById('kqrDropZone');
        if (dz) dz.style.display = dept === 'data' ? 'block' : 'none';
        // Refresh the badge label — non-data depts don't need the "Data Only" lock
        var badge = qrs.querySelector('.kqr-hdr-badge');
        if (badge) badge.style.display = dept === 'data' ? '' : 'none';
        kqrRestoreSnapshot();
      } else {
        qrs.style.display = 'none';
      }
    };
  })();

